{
  // WORKAROUND (added 2026-07-27) for srazzak/zed-mdx#21:
  // https://github.com/srazzak/zed-mdx/issues/21
  //
  // The zed-mdx extension pins typescript@7.0.2 in its own work dir. TypeScript 7
  // is the native Go port and ships no JS API, so its lib/ has no typescript.js or
  // tsserverlibrary.js. mdx-analyzer is Volar-based and loads TypeScript in-process
  // as a JS library, before it reads typescript.enabled, so it dies at initialize:
  //   "Can't find typescript.js or tsserverlibrary.js in .../work/mdx/node_modules/typescript/lib"
  // Pointing tsdk at this repo's TypeScript 5.8 gives it a loadable JS API.
  //
  // REMOVE THIS once zed-mdx#21 is fixed and the extension is updated. Note the
  // Zed tsgo extension does NOT fix this: it serves TypeScript/TSX/JS/JSX over LSP
  // and cannot be loaded in-process by Volar.
  //
  // The path is absolute (Volar resolves tsdk against the language server's cwd,
  // not the workspace root) and therefore machine-specific to Mark's checkout.
  "lsp": {
    "mdx-analyzer": {
      "initialization_options": {
        "typescript": {
          "tsdk": "/Users/marklevison/Documents/GitHub/APR/agile-pain-relief-astro/node_modules/typescript/lib"
        }
      }
    }
  }
}

